package app.runsolo.core.route

import app.runsolo.core.json.Json
import app.runsolo.core.testio.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue

/**
 * Dart/Kotlin parity for [RetraceDetector]: the vectors in
 * `packages/run_engine/test/fixtures/retrace/vectors.json` (generated by the Dart engine, never
 * edited) are replayed point by point, and every field of every state must equal the Dart one
 * to within 0.5 m. The Dart side replays the same file (retrace_parity_test.dart).
 */
class RetraceParityTest {
    private val file = File("../../packages/run_engine/test/fixtures/retrace/vectors.json")

    private fun num(v: Any?): Double? = (v as Number?)?.toDouble()

    private fun near(label: String, expected: Any?, actual: Double?) {
        val e = num(expected)
        if (e == null) {
            assertNull(actual, label)
        } else {
            assertNotNull(actual, label)
            assertEquals(e, actual, 0.5, label)
        }
    }

    @Test
    fun `every vector state equals the Dart engine's`() {
        assertTrue(file.exists(), "missing ${file.path}")
        @Suppress("UNCHECKED_CAST")
        val vectors = Json.parseObject(file.readText())["vectors"] as List<Map<String, Any?>>
        assertTrue(vectors.size >= 4)
        var retracingSeen = 0
        for (v in vectors) {
            val name = v["name"] as String
            @Suppress("UNCHECKED_CAST")
            val points = v["points"] as List<List<Any?>>
            @Suppress("UNCHECKED_CAST")
            val states = v["states"] as List<List<Any?>>
            assertEquals(points.size, states.size, name)
            val d = RetraceDetector()
            for (i in points.indices) {
                val p = points[i]
                val s = d.add(
                    lat = num(p[0])!!,
                    lon = num(p[1])!!,
                    elevM = num(p[2]),
                    distM = if (p.size > 3) num(p[3]) else null,
                )
                val e = states[i]
                val at = "$name #$i"
                assertEquals(e[0] as Boolean, s.retracing, "$at retracing")
                assertEquals(e[1] as String?, s.direction?.name, "$at direction")
                near("$at distanceToStartM", e[2], s.distanceToStartM)
                near("$at climbAheadM", e[3], s.climbAheadM)
                near("$at descentAheadM", e[4], s.descentAheadM)
                near("$at heightVsStartM", e[5], s.heightVsStartM)
                if (s.retracing) retracingSeen++
            }
        }
        assertTrue(retracingSeen > 100, "the vectors must exercise a retrace, saw $retracingSeen states")
    }
}
